Alright, let’s do **complex number addition using operator overloading** in C++.  

Here’s a clean, working example 👇  

```cpp
#include <iostream>
using namespace std;

class Complex {
    float real;
    float imag;

public:
    // Default constructor
    Complex() {
        real = 0;
        imag = 0;
    }

    // Parameterized constructor
    Complex(float r, float i) {
        real = r;
        imag = i;
    }

    // Operator overloading for +
    Complex operator + (Complex c) {
        Complex temp;
        temp.real = real + c.real;
        temp.imag = imag + c.imag;
        return temp;
    }

    // Display function
    void display() {
        cout << real << " + " << imag << "i" << endl;
    }
};

int main() {
    Complex c1(3.5, 2.5);
    Complex c2(1.6, 4.2);

    Complex c3 = c1 + c2;  // Using overloaded + operator

    cout << "First Complex number: ";
    c1.display();

    cout << "Second Complex number: ";
    c2.display();

    cout << "Sum: ";
    c3.display();

    return 0;
}
```

### 🔍 Explanation:
- The `operator +` function adds the real and imaginary parts separately.
- The result is returned as a new `Complex` object.
- When you write `c1 + c2`, the compiler internally calls `c1.operator+(c2)`.

